import{z as B,x as A,o as r,c as d,q as i,j as o,D as e,d as E,s as t,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"GUI 定位","description":"","frontmatter":{"title":"GUI 定位","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gui-grounding.md","filePath":"llm/gui-grounding.md","lastUpdated":1791413859000}'),p={name:"llm/gui-grounding.md"};function g(u,a,m,C,h,c){const l=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="gui-定位" tabindex="-1">GUI 定位 <a class="header-anchor" href="#gui-定位" aria-label="Permalink to &quot;GUI 定位&quot;">​</a></h1><div class="epigraph"><p>屏幕上的「提交」是一块像素控件，不是自然图里的物体名词。点偏一个图标，动作就错成另一个 API。</p><footer>—— Cheng 等 SeeClick / ScreenSpot；Hong 等 CogAgent</footer></div><p><a href="/llm/grounding-referring">上一课</a>在照片上输出框。缺口是 GUI：截图、图标、文字按钮、多层窗口，目标是可点击的点或控件框，供代理执行。后课图表默认：又一类必须读结构的人造画布，但任务从点击换成读数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自然图预训练（<a href="/llm/clip">CLIP</a>、<a href="/llm/vit-as-encoder">ViT</a>）看的是物体与场景。UI 是平面设计：细字、低对比图标、重复列表项，224 squish 会先毁掉可点目标。指令「点击关闭」在不同皮肤下外观不同，必须靠文字、位置与邻近元素，而不是「关闭按钮」这个物体类。</p><p><span class="marginnote">「224 squish」指把任意比例的截图硬压成 ViT 默认的 224×224 输入：1920×1080 的桌面面积约是它的 41 倍，压完按钮文字糊成一团。这就是 GUI 模型要高分辨率或切块编码、不能照搬自然图预处理的原因。</span></p><p>SeeClick 把 GUI grounding 从代理规划里拆出来：先在截图上把指令落到坐标，再谈规划。ScreenSpot 覆盖移动 / 桌面 / Web，按文本控件与图标分列——图标更难，因为少了 OCR 捷径。CogAgent 用更高分辨率视觉与 GUI 数据训专门的截图理解。</p><p><span class="marginnote">输出点还是框是协议。点击任务常用归一化坐标；框便于调试，但代理最终要一个点。元素 HTML 树若可得，像素 grounding 仍必要：渲染后的真源是截图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：截图–指令–坐标三元组，覆盖分辨率与主题。模型侧：原生或 <a href="/llm/anyres">AnyRes</a> 分辨率 + 二维位置；<a href="/llm/llava-projector">LLaVA 投影器</a> 浅桥仍可用，但冻 CLIP、低分辨率几乎做不成图标。评测：点击是否落在金标控件内（ScreenSpot），不要用 RefCOCO IoU 代替。规划基准（Mind2Web 等）应与纯 grounding 分列，否则分不清是看错还是计划错。</p><p><span class="marginnote">常见误区：拿 RefCOCO 的 IoU 高分当 GUI 能力。IoU 容忍把框画大一点凑重叠，而点击必须落进控件内部——偏半个按钮就可能触发另一个动作。ScreenSpot 用「点是否命中金标控件」判定，两种指标不可互换。</span></p>',11)),(r(),o(s,null,{default:e(()=>[t(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOT%5B%22%E5%B1%8F%E5%B9%95%E6%88%AA%E5%9B%BE%22%5D%20--%3E%20VIT%5B%22%E9%AB%98%E5%88%86%E8%BE%A8%E7%8E%87%20ViT%22%5D%0A%20%20INS%5B%22%E7%82%B9%E5%87%BB%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20LLM%5B%22LLM%22%5D%0A%20%20VIT%20--%3E%20LLM%0A%20%20LLM%20--%3E%20XY%5B%22%E7%82%B9%E5%87%BB%E5%9D%90%E6%A0%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"GUI 定位把语言约束（标签文本、第 n 个、相对「搜索框右侧」）打到细格子上。OCR 能力与分辨率直接决定文本按钮；图标依赖外观与布局关系。语言先验「关闭在右上角」在移动 App 里经常错，必须被像素证据覆盖。",-1)),a[5]||(a[5]=n("p",null,"一条指令落地时，模型实际在几种线索之间做裁决：",-1)),(r(),o(s,null,{default:e(()=>[t(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8C%87%E4%BB%A4%3A%20%E7%82%B9%E5%87%BB%E5%85%B3%E9%97%AD%22%5D%20--%3E%20C%7B%22%E5%8F%AF%E7%94%A8%E7%BA%BF%E7%B4%A2%22%7D%0A%20%20C%20--%3E%20T%5B%22%E6%96%87%E6%9C%AC%E7%BA%BF%E7%B4%A2%3A%20OCR%20%E5%8C%B9%E9%85%8D%E6%A0%87%E7%AD%BE%22%5D%0A%20%20C%20--%3E%20P%5B%22%E4%BD%8D%E7%BD%AE%E5%85%88%E9%AA%8C%3A%20%E5%B8%B8%E8%A7%81%E6%91%86%E6%94%BE%E4%B9%A0%E6%83%AF%22%5D%0A%20%20C%20--%3E%20N%5B%22%E9%82%BB%E8%BF%91%E5%85%B3%E7%B3%BB%3A%20%E6%90%9C%E7%B4%A2%E6%A1%86%E5%8F%B3%E4%BE%A7%22%5D%0A%20%20T%20--%3E%20J%5B%22%E5%83%8F%E7%B4%A0%E8%AF%81%E6%8D%AE%E6%9C%80%E7%BB%88%E8%A3%81%E5%86%B3%22%5D%0A%20%20P%20--%3E%20J%0A%20%20N%20--%3E%20J%0A%20%20J%20--%3E%20PT%5B%22%E8%90%BD%E7%82%B9%E6%98%AF%E5%90%A6%E8%90%BD%E5%9C%A8%E9%87%91%E6%A0%87%E6%8E%A7%E4%BB%B6%E5%86%85%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>点对了不等于任务完成：弹窗、延迟、权限会让执行失败。下一课换成图表与表：结构是轴与单元格，不是可点控件。</p><p><span class="marginnote">可以把它想成「眼睛」与「手」的分工：grounding 只负责眼睛看准坐标；弹窗、加载延迟、权限确认是「手」执行时遇到的意外。评测把两者混在一起，就分不清是看错了还是没点到。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GUI 定位是截图像素上的指代，服务点击而不是描述。</li><li>分辨率与 UI 数据比加宽投影更关键。</li><li>ScreenSpot 把文本控件与图标分开报。</li><li>出处：SeeClick；CogAgent。</li></ul>',5))])}const I=B(p,[["render",g]]);export{D as __pageData,I as default};
